        body: "첫째, 추출입니다. xgettext가 소스 전체를 훑어 _() 안의 영어 문장을 전부 뽑습니다. 그것으로 원본 목록(.pot)을 만듭니다. 개발자가 번역 대상을 손으로 관리하지 않습니다. 둘째, 번역입니다. 번역가가 그 목록을 복사해 ko.po를 만들고 msgstr를 채웁니다. 셋째, 실행입니다. msgfmt가 사람이 읽는 .po를 기계가 빨리 읽는 .mo로 컴파일합니다. 프로그램은 실행 중에 사용자의 로케일에 맞는 폴더의 .mo를 펼칩니다. 데스크톱에서는 LANG 환경변수가, 웹 서버에서는 Accept-Language 헤더가 그 로케일을 알려 줍니다. 코드의 _('Checkout')은 어느 언어에서든 똑같습니다. 어느 사전을 펼칠지만 바깥에서 정해집니다. 2단계처럼 빌드가 언어를 고르는 것이 아닙니다. 실행 중에 고르는 쪽으로 무게가 옮겨 갑니다.",
        code: "# 1. 추출 — 소스를 훑어 _() 안의 문장을 전부 뽑는다\nxgettext --keyword=_ -o locales/messages.pot src/**/*.vue\n\n# 2. 새 언어 추가 — 원본 목록을 복사해 빈 사전을 만든다 (번역가가 채운다)\nmsginit -i locales/messages.pot -l de_DE -o locales/de_DE/LC_MESSAGES/messages.po\n\n# 3. 컴파일 — 사람용 .po 를 기계용 .mo 로\nmsgfmt locales/ko_KR/LC_MESSAGES/messages.po -o locales/ko_KR/LC_MESSAGES/messages.mo\n\n# 실행 — 로케일이 어느 폴더를 펼칠지 정한다\nLANG=ja_JP.UTF-8 ./app      # _('Checkout') → 購入手続き",
