        code: "// 코드 — 같은 영어, 다른 뜻\n<button>{{ _('Open') }}</button>          // 동사: 열기\n<span class=\"badge\">{{ _('Open') }}</span> // 형용사: 영업 중\n\n// ko.po — 열쇠가 하나라 번역도 하나뿐이다\n// msgid \"Open\"\n// msgstr \"열기\"        ← 배지에도 '열기'가 찍힌다\n\n// 사후 해법: 문맥을 열쇠에 덧붙인다\n<span class=\"badge\">{{ pgettext('store status', 'Open') }}</span>\n// msgctxt \"store status\"\n// msgid \"Open\"\n// msgstr \"영업 중\"",
