        code: "경우              언제 생기나                          겉모습                           들통나는 때\nㄱ 원문 수정       Checkout → Proceed to checkout       세 언어가 fuzzy, 확인 전엔 영어 노출   msgmerge 돌린 직후\nㄴ 동음이의        버튼 Open, 배지 Open                  한쪽에 틀린 번역                   그 화면을 그 언어로 볼 때\nㄷ 원문 언어 QA    영어 화면엔 '빠짐' 이 없다              다른 언어의 빠짐이 안 보인다          그 언어 사용자가 볼 때\nㄹ 변수 열쇠       _(label) — 리터럴이 아니다             .pot 에 없음 → 영어 그대로           번역가가 아니라 사용자가\nㅁ 문단 열쇠       약관 한 문단을 _() 에 넣음             쉼표 하나에 전부 끊어진다            원문을 손볼 때마다\n\n# ㄹ — xgettext 는 글자 그대로 적힌 것만 뽑는다\nconst LABELS = ['Paid', 'Shipped', 'Canceled'];\n<span>{{ _(LABELS[order.state]) }}</span>     ← .pot 에 Paid/Shipped/Canceled 가 없다\n<span>{{ _('Paid') }}</span>                   ← 이건 뽑힌다",
