        body: "3단계에서는 xgettext가 코드에서 사전을 만들어 냈습니다. 코드가 원본이고 사전은 거기서 뽑은 것이라, 둘이 어긋날 길이 좁았습니다. 4단계는 다릅니다. 코드의 열쇠와 사전의 열쇠를 각각 사람이 손으로 적습니다. 장부가 둘입니다. 둘을 맞춰 보는 장치는 실행 중의 문자열 비교 하나뿐입니다. 그래서 어긋남은 세 종류로 정리됩니다. 첫째, 코드에는 있고 사전에는 없다. 오타(ㄱ), 추가 누락(ㄴ), 바꾸다 남김(ㄷ), 가지 호출(ㅁ)이 여기입니다. 겉모습은 열쇠 노출입니다. 둘째, 사전에는 있고 코드에는 없다. 죽은 열쇠(ㄹ)입니다. 겉모습은 없고 번역 비용만 샙니다. 셋째, 둘 다 있는데 뜻이 어긋난다. 썩은 이름표(ㅂ), common 재사용(ㅅ), 빈 값(ㅇ)이 여기입니다. 겉모습은 '멀쩡해 보이는 틀린 문장'이라 가장 늦게 들통납니다. 사전이 언어 수만큼이라 첫째와 셋째는 언어마다 따로 납니다. ko에서 멀쩡해도 ja에서 납니다. 1~3단계의 문제는 방법을 바꿔 풀었습니다. 이 문제는 장부를 하나로 합치거나(사전에서 열쇠 타입을 뽑아 코드가 그 타입만 받게 하는 10단계), 비교 지점을 앞당기는(린트·CI) 도구로 풉니다.",
