        body: "경우 ㄱ, 빈칸 이름을 번역합니다. {count}를 {갯수}로 적었습니다. 경고가 아닙니다. 실제로 돌려 보면 t()가 SyntaxError를 던집니다. 'Invalid token in placeholder: 갯수'. 그 문장을 쓰는 컴포넌트가 그리다 멈춥니다. 영어 이름이지만 다른 이름({cnt})이면 조용히 빈칸만 빕니다. '상품 개'가 나옵니다. 경우 ㄴ, 두 칸 복수형의 규칙이 뜻밖입니다. 번역가가 '상품 없음 | 상품 {count}개'라고 적었습니다. 0일 때 '상품 없음'이 나오길 바란 것입니다. 그런데 Vue I18n의 두 칸 규칙은 1이면 첫 칸, 나머지는 둘째 칸입니다. 실제로 돌려 보면 0은 '상품 0개', 1은 '상품 없음'이 됩니다. 의도와 정반대입니다. 경우 ㄷ, 복수 규칙이 언어마다 다릅니다. 러시아어는 1·21·31이 한 꼴, 2~4·22~24가 다른 꼴, 5~20이 또 다른 꼴입니다. 기본 규칙은 영어식이라 세 칸을 적어도 1→둘째 칸, 2→셋째 칸, 21→셋째 칸으로 셋 다 틀립니다. pluralizationRules로 언어별 규칙을 넣어야 합니다. 경우 ㄹ, 특수 기호입니다. 문의 메일 help@shop.com을 적으면 @가 링크 문법으로 읽혀 'Invalid linked format'을 던집니다. 'A | B 를 고르세요'는 세로줄이 복수형 칸으로 읽혀 'A'만 나옵니다. {'@'}처럼 피해 적어야 합니다. 경우 ㅁ, 한국어 조사입니다. '{name}을 담았습니다'는 '사과을', '바나나을'이 됩니다. 문법에 받침을 보고 을/를을 고르는 장치가 없습니다. 경우 ㅂ, 성과 격입니다. 프랑스어 ajouté/ajoutée, 독일어의 격변화는 명사에 따라 형용사가 바뀝니다. Vue I18n 문법에는 조건 분기(select)가 없어 코드가 갈라야 합니다. 그러면 문장 조각이 다시 코드로 돌아옵니다.",
        code: "경우             언제 생기나                           겉모습                                  들통나는 때\nㄱ 빈칸 이름       {count} → {갯수}                     SyntaxError. 컴포넌트가 그리다 멈춤          그 문장을 처음 부를 때\n                 {count} → {cnt}                      '상품 개' (빈칸이 조용히 빈다)               사용자가 볼 때\nㄴ 두 칸 규칙      '상품 없음 | 상품 {count}개'           0 → '상품 0개',  1 → '상품 없음'            0개·1개 화면에서\nㄷ 언어별 규칙     러시아어 세 칸을 기본 규칙으로           1 → товара(✗)  2 → товаров(✗)  21 → товаров(✗)  러시아어 사용자가\nㄹ 특수 기호       help@shop.com,  'A | B'               @ → SyntaxError,  | → 'A' 만               그 문장을 처음 부를 때\nㅁ 조사            '{name}을 담았습니다'                  '사과을 담았습니다'                        한국어 사용자가 매번\nㅂ 성·격           ajouté / ajoutée                     문법에 분기가 없어 코드로 돌아간다            프랑스어·독일어에서\n\n// 실제로 돌려 보면 (vue-i18n 11.4, Node 24)\nt('c', { count: 3 })   // 메시지 '상품 {갯수}개'  → throws SyntaxError: Message compilation error: Invalid token in placeholder: '갯수'\nt('c', { count: 3 })   // 메시지 '상품 {cnt}개'   → \"상품 개\"\nt('items', 0)          // '상품 없음 | 상품 {count}개' → \"상품 0개\"      t('items', 1) → \"상품 없음\"\nt('items', 21, { n })  // '{n} товар | {n} товара | {n} товаров' → \"21 товаров\"  (맞는 답: товар)\nt('mail')              // '문의: help@shop.com'  → throws: Invalid linked format\nt('ok')                // \"문의: help{'@'}shop.com\" → \"문의: help@shop.com\"",
        codeLang: "text",
