        label: "문제의 구조: 문장이 세 사람이 함께 지켜야 하는 문법이 되었다",
        body: "4단계까지 사전의 값은 그냥 글이었습니다. 무엇을 적어도 그대로 보였습니다. 5단계부터 값은 작은 프로그램입니다. 중괄호·세로줄·골뱅이가 명령입니다. 프로그램에는 문법 검사가 필요합니다. 그런데 그 검사가 일어나는 시점이 실행 중에 그 문장을 처음 부를 때입니다. 그래서 틀린 문장은 그 화면을 그 언어로 열 때 터집니다(ㄱ, ㄹ). 문법을 지켜야 하는 사람이 셋입니다. 문법을 만든 라이브러리, 문장을 적는 번역가, 값을 넘기는 개발자입니다. 번역가는 프로그래머가 아닌데 이 문법을 알아야 합니다. 그리고 이 문법은 영어를 기준으로 만들어졌습니다. 복수형 칸의 규칙(ㄴ, ㄷ)과 조사·성·격(ㅁ, ㅂ)은 영어에 없는 문제라 문법에도 없습니다. 땜질은 두 방향입니다. 문법을 키우거나(14단계의 MF2가 select와 CLDR 복수 규칙을 넣습니다), 문법을 검사하는 도구를 두는 것입니다(9단계의 사전 컴파일이 빌드 때 ㄱ·ㄹ을 잡고, 11단계의 워크플로가 빈칸 이름을 원문과 대조합니다).",
        code: "4단계의 값:  \"결제하기\"                          → 무엇을 적어도 그대로 보인다\n5단계의 값:  \"상품 없음 | 상품 {count}개\"           → 작은 프로그램. 파서가 읽는다. 틀리면 던진다\n\n문법을 지키는 세 사람          어디서 틀리나                             언제 들통나나\n라이브러리 (문법을 정함)       영어 기준 복수 규칙. 조사·성·격 분기 없음       러시아어·한국어·프랑스어 화면에서   ㄴ ㄷ ㅁ ㅂ\n번역가 (문장을 적음)          {count} → {갯수},  @ 를 그냥 씀              그 문장을 처음 부를 때 SyntaxError   ㄱ ㄹ\n개발자 (값을 넘김)            {count} 에 count 아닌 n 을 넘김              빈칸이 비어 '상품 개'               ㄱ\n\n검사 시점 = 실행 중 첫 호출\n  → 빌드 때로 당기는 것: 9단계 (사전 컴파일)\n  → 표에서 대조하는 것: 11단계 (빈칸 이름 = 원문의 빈칸 이름인가)\n  → 문법 자체를 키우는 것: 14단계 (select, CLDR 복수 규칙)",
