        code: "// src/main.js — 형식의 이름과 옵션만 적는다. 글자는 Intl이 만든다\nconst i18n = createI18n({\n  datetimeFormats: {\n    ko:      { long: { year: 'numeric', month: 'long', day: 'numeric', weekday: 'short' } },\n    'en-US': { long: { year: 'numeric', month: 'long', day: 'numeric', weekday: 'short' } },\n    ja:      { long: { year: 'numeric', month: 'long', day: 'numeric', weekday: 'short' } },\n  },\n  numberFormats: {\n    ko:      { currency: { style: 'currency', currency: 'KRW' } },\n    'en-US': { currency: { style: 'currency', currency: 'USD' } },\n    ja:      { currency: { style: 'currency', currency: 'JPY' } },\n  },\n});\n\n// src/Order.vue — 이름만 부른다\n<p>{{ $d(order.paidAt, 'long') }} · {{ $n(order.total, 'currency') }}</p>",
