        label: "로케일 없는 toLocaleString()은 어디서 돌아가느냐에 따라 다르다",
        body: "1단계에서 천 단위 쉼표 버그를 고치며 total.toLocaleString()을 썼습니다. 이것도 사실은 Intl을 부르는 것이었습니다. 다만 로케일 인자를 비워 두었습니다. 그러면 '지금 이 코드가 돌아가는 환경의 로케일'을 씁니다. 브라우저에서는 사용자 OS의 설정입니다. 서버에서는 서버의 설정입니다. 한국어 화면을 보는 사용자의 OS가 영어라면 쉼표는 맞지만 통화는 틀립니다. 서버에서 먼저 그린 HTML과 브라우저가 다시 그린 HTML이 다를 수도 있습니다. 로케일은 사용자가 고른 언어에서 와야 합니다. $n은 그 값을 알고 있습니다. 이것이 이 단계의 핵심입니다. 날짜도 같습니다. date-fns의 format(date, 'yyyy.MM.dd')는 어느 언어에서나 2026.11.11을 찍습니다. 그것은 한국어 관례입니다.",
        code: "// 2단계의 버그 수정 — 돌아가는 환경의 로케일을 쓴다. 사용자의 언어가 아니다\n<p>{{ total.toLocaleString() }}원</p>          // 서버 en-US + 브라우저 ko → 두 HTML이 다를 수 있다\n\n// 6단계 — 사용자가 고른 로케일로 찍는다\n<p>{{ $n(total, 'currency') }}</p>             // locale이 ko면 ₩, en-US면 $, ja면 ￥\n\n// 날짜도 같다. 고정 패턴은 한 언어의 관례다\nformat(date, 'yyyy.MM.dd HH:mm')                 // 어느 언어에서나 2026.11.11 09:05\n$d(date, 'short')                                // ko 2026. 11. 11.  en-US 11/11/2026  ja 2026/11/11",
