        body: "경우 ㄱ, 로케일을 비웠습니다. toLocaleString()에 로케일을 안 넘기면 실행 환경의 기본값이 들어옵니다. 서버의 Node는 보통 en-US입니다. 실제로 돌려 보면 LANG=C인 서버에서 2026년 11월 20일이 '11/20/2026'으로 찍힙니다. 한국어 사용자의 브라우저는 '2026. 11. 20.'으로 찍습니다. 서버가 그린 HTML과 브라우저가 다시 그린 것이 달라 하이드레이션 불일치 경고가 납니다. 사용자 기기의 OS가 영어이고 사이트는 한국어여도 같은 일이 납니다. 글은 한국어인데 날짜만 영어식입니다. 경우 ㄴ, 날짜만 있는 문자열입니다. new Date('2026-11-11')은 표준에 따라 UTC 자정으로 읽힙니다. 시각이 붙은 '2026-11-11T00:00'은 현지 자정으로 읽힙니다. 실제로 돌려 보면 로스앤젤레스 시간대에서 앞의 것은 11월 10일, 뒤의 것은 11월 11일로 찍힙니다. 생일·출시일·마감일이 하루 밀립니다. 경우 ㄷ, 반올림입니다. 원화는 소수 자릿수가 0이라 1234.5원을 포맷하면 ₩1,235가 됩니다. 실제로 돌려 보면 그 줄이 셋이면 화면의 합은 ₩3,705인데 실제 합 3703.5를 포맷하면 ₩3,704입니다. 영수증의 합이 맞지 않습니다. 경우 ㄹ, 통화 기호가 로케일을 따릅니다. 실제로 돌려 보면 ko-KR에서 USD는 'US$1,234.00', en-US에서 KRW는 '₩1,234'입니다. 결제 통화는 언어가 아니라 결제 수단이 정합니다. 일본어 사용자가 원화로 결제하는데 로케일만 보고 엔 형식을 쓰면 틀립니다. 경우 ㅁ, 규칙 데이터의 버전입니다. 서버의 Node와 사용자의 브라우저가 다른 ICU를 가지면 같은 로케일도 다른 글자를 냅니다. 공백 글자의 종류, 약어의 모양이 바뀐 적이 있습니다. 경우 ㅂ, 지원 범위입니다. Intl.Segmenter는 2024년 봄까지 Firefox에 없었습니다. 있다고 믿고 부르면 그 브라우저에서 TypeError입니다.",
        code: "경우              언제 생기나                               겉모습                                     들통나는 때\nㄱ 로케일 비움      toLocaleString()                          서버 11/20/2026 vs 브라우저 2026. 11. 20.    하이드레이션 경고, 영어 OS 기기\nㄴ 날짜만 문자열    new Date('2026-11-11')                    LA 에서 11월 10일                           서울 밖 사용자가\nㄷ 반올림          KRW 1234.5 × 3                            ₩1,235 ×3 = ₩3,705 ≠ 합계 ₩3,704             영수증을 더해 볼 때\nㄹ 통화 ≠ 언어     ja 사용자, KRW 결제                        로케일만 보면 ¥ 형식                          결제 금액을 볼 때\nㅁ 데이터 버전      서버 ICU ≠ 브라우저 ICU                    같은 로케일, 다른 공백·약어                     하이드레이션 경고\nㅂ 지원 범위        Intl.Segmenter (Firefox 2024 봄 전)        TypeError                                  그 브라우저에서\n\n// 실제로 돌려 보면 (Node 24)\nLANG=C  new Date('2026-11-20T10:00:00+09:00').toLocaleDateString()   // → \"11/20/2026\"   서버 기본 로케일 en-US\nTZ=America/Los_Angeles  new Date('2026-11-11').toLocaleDateString('ko-KR')        // → \"2026. 11. 10.\"  ← 하루 전\nTZ=America/Los_Angeles  new Date('2026-11-11T00:00').toLocaleDateString('ko-KR')  // → \"2026. 11. 11.\"\nnew Intl.NumberFormat('ko-KR', { style: 'currency', currency: 'KRW' }).format(1234.5)   // → \"₩1,235\"\nnew Intl.NumberFormat('ko-KR', { style: 'currency', currency: 'USD' }).format(1234)     // → \"US$1,234.00\"\nnew Intl.NumberFormat('en-US', { style: 'currency', currency: 'KRW' }).format(1234)     // → \"₩1,234\"",
