        code: "// 협상 — 명시적인 신호가 암묵적인 신호를 이긴다\nfunction resolveLocale(req) {\n  return (\n    req.query.lang                                   // 1. 주소  ?lang=en  (가장 명시적)\n    ?? req.cookies.i18n_redirected                   // 2. 쿠키  전에 직접 고른 값\n    ?? pickSupported(req.headers['accept-language'])  // 3. 브라우저  ja-JP,ja;q=0.9,en;q=0.8\n    ?? 'ko'                                          // 4. 기본값\n  );\n}\n\n// 지원하는 언어 중 첫 번째로 맞는 것만 고른다 — 브라우저가 보낸 순서를 존중한다\nconst SUPPORTED = ['ko', 'en', 'ja', 'zh', 'zh-Hant'];\nfunction pickSupported(header = '') {\n  const wanted = header.split(',').map((s) => s.split(';')[0].trim());\n  return wanted.find((w) => SUPPORTED.includes(w)) ?? wanted.map((w) => w.split('-')[0]).find((w) => SUPPORTED.includes(w));\n}",
