      "브라우저에서는 사용자가 한 사람입니다. 그래서 i18n 인스턴스도 하나면 됩니다. 서버가 HTML을 먼저 그리는 사이트(SSR)는 다릅니다. 서버 프로세스 하나가 한국어 사용자와 영어 사용자의 요청을 동시에 처리합니다. 둘이 하나의 인스턴스를 함께 쓰고, 요청마다 locale만 바꿔 꽂으면 어떻게 될까요. 한 요청이 그리는 도중에 다른 요청이 locale을 바꿉니다. 한국어 사용자에게 영어 HTML이 나갑니다. 실제로 재현되는 사고입니다. 이 단계는 세 가지를 합니다. 인스턴스를 요청마다 만듭니다. 로케일을 서버에서 정합니다. 캐시가 언어를 섞지 않게 합니다. '지금 표준'의 마지막 조각입니다.",
