        code: "// 서버에 하나만 있는 인스턴스 — 이렇게 쓰면 섞인다\nconst shared = createI18n({ legacy: false, locale: 'ko', messages });\n\nasync function handle(req) {\n  shared.global.locale.value = req.locale;      // 요청 A: ko\n  const app = createSSRApp(App).use(shared);\n  return renderToString(app);                   // A가 await 하는 사이 요청 B가 locale을 en으로 바꾼다\n}\n\n// 두 요청이 겹칠 때\n// 요청 A (ko) → <h1>Cart</h1>        ← 한국어 사용자가 영어를 받았다\n// 요청 B (en) → <h1>Cart</h1>",
